	private final StashTier tier;
	private final int objectId;
	private final String displayName;
	private final WorldPoint[] worldPoints;

	StashUnit(StashTier tier, int objectId, String displayName, WorldPoint... worldPoints)
	{
		this.tier = tier;
		this.objectId = objectId;
		this.displayName = displayName;
		this.worldPoints = worldPoints;
	}

	private static final Map<Integer, StashUnit> BY_OBJECT_ID = new HashMap<>();

	static
	{
		for (StashUnit unit : values())
		{
			BY_OBJECT_ID.put(unit.objectId, unit);
		}
	}

	/** Returns the STASH unit whose built object has the given id, or null. */
	public static StashUnit forObjectId(int objectId)
	{
		return BY_OBJECT_ID.get(objectId);
	}

	/**
	 * Returns the closest STASH unit to the given world point within {@code maxDistance} tiles
	 * (same plane), or null if none are that close. Used to attribute a deposit/withdraw chat
	 * message to a unit when the menu interaction did not identify one (e.g. in instances).
	 */
	public static StashUnit nearest(WorldPoint from, int maxDistance)
	{
		if (from == null)
		{
			return null;
		}

		StashUnit best = null;
		int bestDistance = Integer.MAX_VALUE;
		for (StashUnit unit : values())
		{
			for (WorldPoint wp : unit.worldPoints)
			{
				if (wp.getPlane() != from.getPlane())
				{
					continue;
				}
				int distance = wp.distanceTo2D(from);
				if (distance <= maxDistance && distance < bestDistance)
				{
					best = unit;
					bestDistance = distance;
				}
			}
		}
		return best;
	}
}

package com.stashtracker;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import javax.inject.Inject;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

/**
 * Marks items in the inventory, bank and equipment that still need to be deposited into a STASH
 * unit, so the player doesn't accidentally drop, sell or alch a needed item. The marker is a small
 * dot in the top-right corner of the item so it stays unobtrusive in a full bank.
 */
class StashItemOverlay extends WidgetItemOverlay
{
	private static final Color HALO = new Color(0, 0, 0, 190);
	private static final int DOT = 6;

	private final StashTrackerPlugin plugin;
	private final StashTrackerConfig config;

	@Inject
	StashItemOverlay(StashTrackerPlugin plugin, StashTrackerConfig config)
	{
		this.plugin = plugin;
		this.config = config;
		showOnInventory();
		showOnBank();
		showOnEquipment();
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem itemWidget)
	{
		if (!config.highlightInventoryItems())
		{
			return;
		}

		// colour is the clue tier of the STASH that needs this item; null means not needed
		final Color color = plugin.neededItemColor(itemId);
		if (color == null)
		{
			return;
		}

		final Rectangle bounds = itemWidget.getCanvasBounds();
		final int x = bounds.x + bounds.width - DOT;
		final int y = bounds.y;

		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		// dark halo for contrast against bright item sprites, then the tier-coloured dot
		graphics.setColor(HALO);
		graphics.fillOval(x - 1, y - 1, DOT + 2, DOT + 2);
		graphics.setColor(color);
		graphics.fillOval(x, y, DOT, DOT);
	}
}

package com.stashtracker;

import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Insets;
import javax.swing.JScrollPane;
import javax.swing.SwingUtilities;

/**
 * A {@link FlowLayout} that wraps components onto multiple rows and — unlike plain FlowLayout —
 * reports a correct preferred size for those wrapped rows. This is what lets a wrapping grid behave
 * inside a vertical {@code BoxLayout} / scroll pane. Based on Rob Camick's well-known WrapLayout.
 */
class WrapLayout extends FlowLayout
{
	WrapLayout(int align, int hgap, int vgap)
	{
		super(align, hgap, vgap);
	}

	@Override
	public Dimension preferredLayoutSize(Container target)
	{
		return layoutSize(target, true);
	}

	@Override
	public Dimension minimumLayoutSize(Container target)
	{
		final Dimension minimum = layoutSize(target, false);
		minimum.width -= (getHgap() + 1);
		return minimum;
	}

	private Dimension layoutSize(Container target, boolean preferred)
	{
		synchronized (target.getTreeLock())
		{
			// find the width to wrap against, walking up until a laid-out ancestor is found
			Container container = target;
			while (container.getSize().width == 0 && container.getParent() != null)
			{
				container = container.getParent();
			}

			int targetWidth = container.getSize().width;
			if (targetWidth == 0)
			{
				targetWidth = Integer.MAX_VALUE;
			}

			final int hgap = getHgap();
			final int vgap = getVgap();
			final Insets insets = target.getInsets();
			final int horizontalInsetsAndGap = insets.left + insets.right + (hgap * 2);
			final int maxWidth = targetWidth - horizontalInsetsAndGap;

			final Dimension dim = new Dimension(0, 0);
			int rowWidth = 0;
			int rowHeight = 0;

			final int members = target.getComponentCount();
			for (int i = 0; i < members; i++)
			{
				final Component m = target.getComponent(i);
				if (!m.isVisible())
				{
					continue;
				}

				final Dimension d = preferred ? m.getPreferredSize() : m.getMinimumSize();
				if (rowWidth + d.width > maxWidth)
				{
					addRow(dim, rowWidth, rowHeight);
					rowWidth = 0;
					rowHeight = 0;
				}

				if (rowWidth != 0)
				{
					rowWidth += hgap;
				}

				rowWidth += d.width;
				rowHeight = Math.max(rowHeight, d.height);
			}

			addRow(dim, rowWidth, rowHeight);

			dim.width += horizontalInsetsAndGap;
			dim.height += insets.top + insets.bottom + vgap * 2;

			final Container scrollPane = SwingUtilities.getAncestorOfClass(JScrollPane.class, target);
			if (scrollPane != null && target.isValid())
			{
				dim.width -= (hgap + 1);
			}

			return dim;
		}
	}

	private void addRow(Dimension dim, int rowWidth, int rowHeight)
	{
		dim.width = Math.max(dim.width, rowWidth);
		if (dim.height > 0)
		{
			dim.height += getVgap();
		}
		dim.height += rowHeight;
	}
}

package com.stashtracker;

import java.awt.Color;
import lombok.Getter;
